// KES Agent: header afterRender JS (shared suite prelude + this dashboard's KPIs)
(function () {
  var ROOT_ID = 'hx-bursa';
  try {

  var s = (context && context.panelData && context.panelData.series) ? context.panelData.series : [];
  function lastv(v) { if (!v) return undefined; for (var i = v.length - 1; i >= 0; i--) { var x = v[i]; if (x !== null && x !== undefined && isFinite(x)) return Number(x) } return undefined }
  /* rows(ref): [{l: labels, v: last value}] for every series of that query */
  function rows(ref) {
    var out = [];
    for (var si = 0; si < s.length; si++) {
      if (!s[si] || s[si].refId !== ref) continue;
      var f = s[si].fields || [];
      for (var j = 0; j < f.length; j++) {
        if (f[j].type !== 'number') continue;
        var v = lastv(f[j].values && f[j].values.toArray ? f[j].values.toArray() : f[j].values);
        if (v !== undefined) out.push({ l: f[j].labels || {}, v: v });
      }
    }
    return out;
  }
  function one(ref) { var r = rows(ref); return r.length ? r[0].v : undefined }
  function sum(ref) { var r = rows(ref), t = 0; for (var i = 0; i < r.length; i++) t += r[i].v; return r.length ? t : undefined }
  function minRow(r) { var m = null; for (var i = 0; i < r.length; i++) if (!m || r[i].v < m.v) m = r[i]; return m }
  function maxRow(r) { var m = null; for (var i = 0; i < r.length; i++) if (!m || r[i].v > m.v) m = r[i]; return m }
  function byLabel(ref, label) { var r = rows(ref), o = {}; for (var i = 0; i < r.length; i++) { var k = r[i].l[label]; if (k !== undefined) o[k] = r[i].v } return o }
  function has(x) { return x !== undefined && x !== null && isFinite(x) }
  function n0(x) { return has(x) ? String(Math.round(x)) : '–' }
  function ms(sec) { if (!has(sec)) return '–'; var m = sec * 1000; return m >= 10000 ? (m / 1000).toFixed(1) + ' s' : (m >= 100 ? Math.round(m) : (m >= 10 ? m.toFixed(0) : m.toFixed(1))) + ' ms' }
  function plural(n, one_, many) { return n + ' ' + (n === 1 ? one_ : many) }
  function names(a, max) { max = max || 3; return a.length <= max ? a.join(', ') : a.slice(0, max).join(', ') + ' +' + (a.length - max) }
  function esc(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;') }
  var RANK = { na: 0, ok: 1, warn: 2, bad: 3 };
  function worst(a, b) { return RANK[b] > RANK[a] ? b : a }
  /* lower is better: ok under w, warn under b, else bad */
  function low(x, w, b) { return !has(x) ? 'na' : (x < w ? 'ok' : (x < b ? 'warn' : 'bad')) }
  /* higher is better: ok at or above g, warn at or above a, else bad */
  function high(x, g, a) { return !has(x) ? 'na' : (x >= g ? 'ok' : (x >= a ? 'warn' : 'bad')) }
  function el(id) { return document.getElementById(id) }
  var root = el(ROOT_ID);
  /* light theme: ask Grafana, else infer it from the inherited text colour (dark text = light theme) */
  try {
    var th = context.grafana && context.grafana.theme, light = null;
    if (th && typeof th.isDark === 'boolean') light = !th.isDark;
    if (light === null && root && typeof getComputedStyle === 'function') {
      var m = /(\d+)[, ]+(\d+)[, ]+(\d+)/.exec(getComputedStyle(root).color || '');
      if (m) light = (0.299 * m[1] + 0.587 * m[2] + 0.114 * m[3]) < 128;
    }
    if (root && light && String(root.className).indexOf('hx-light') < 0) root.className += ' hx-light';
  } catch (e) { }
  /* fit(): a dynamic-text panel scrolls inside itself when its content is taller than the panel, and that
     captures the page scroll. Find the scrolling ancestor and, while the content overflows it, step through the
     compact levels (hx-fit1 drops the detail line, hx-fit2 also thins the rows and drops the legend). */
  function fit() {
    try {
      if (!root || !root.parentElement || typeof getComputedStyle !== 'function') return;
      root.className = String(root.className).replace(/ hx-fit\d/g, '');
      var box = root.parentElement, found = false;
      /* only a scroller inside this panel counts: stop at the panel chrome (<section>) or the grid item */
      while (box && box !== document.body) {
        var cls = typeof box.className === 'string' ? box.className : '';
        if (box.tagName === 'SECTION' || cls.indexOf('react-grid-item') >= 0) break;
        var oy = getComputedStyle(box).overflowY;
        if ((oy === 'auto' || oy === 'scroll') && box.clientHeight > 0) { found = true; break }
        box = box.parentElement;
      }
      if (!found) return;
      for (var lvl = 1; lvl <= 2 && box.scrollHeight > box.clientHeight + 1; lvl++) root.className += ' hx-fit' + lvl;
    } catch (e) { }
  }
  function dur(sec) { if (!has(sec)) return '–'; var a = Math.abs(sec); if (a < 90) return Math.round(a) + ' s'; if (a < 5400) return Math.round(a / 60) + ' min'; if (a < 172800) return (a / 3600).toFixed(a < 36000 ? 1 : 0) + ' h'; return (a / 86400).toFixed(a < 864000 ? 1 : 0) + ' d' }
  var overall = 'na';
  /* kpi(key, value, unit, status, note): fill one tile; value '–' when undefined */
  function kpi(key, value, unit, status, note) {
    var t = el(ROOT_ID + '-k-' + key); if (!t) return;
    var miss = value === undefined || value === null || value === '–';
    var st = miss ? 'na' : (status || 'na');
    t.setAttribute('data-s', st);
    var c = t.children;
    if (c[1]) c[1].innerHTML = miss ? '–' : esc(value) + (unit ? '<small>' + esc(unit) + '</small>' : '');
    if (c[2]) c[2].textContent = miss ? (note || 'no data') : (note || '');
    if (c[2]) c[2].title = miss ? '' : (note || '');
    overall = worst(overall, st);
  }
  var BADGE = { ok: 'Healthy', warn: 'Attention', bad: 'Action needed', na: 'No data' };
  function verdict(html, status) {
    var st = status || overall;
    if (root) root.setAttribute('data-s', st);
    var b = el(ROOT_ID + '-badge'); if (b) b.lastChild.textContent = BADGE[st];
    var v = el(ROOT_ID + '-verdict'); if (v) v.innerHTML = html;
    fit();
  }

  var issues = [], sev = 'ok';
  function issue(st, text) { issues.push({ st: st, text: text }); sev = worst(sev, st) }
  /* REP and DES come per agent deployment, TEL per namespace. Judge each deployment on its own and each
     namespace against its own exporters, and keep the worst, so a surplus in one cannot hide a shortfall in another. */
  function byWorkload(ref) { var r = rows(ref), o = {}; for (var i = 0; i < r.length; i++) o[(r[i].l.namespace || '') + '/' + (r[i].l.deployment || '')] = r[i].v; return o }
  var repBy = byWorkload('REP'), desBy = byWorkload('DES'), telBy = byLabel('TEL', 'namespace');
  var wlList = Object.keys(desBy); for (var rk in repBy) if (!(rk in desBy)) wlList.push(rk);
  var multi = wlList.length > 1, rep = sum('REP'), des = sum('DES');
  var down = [], short = [], dark = [], repNs = {};
  for (var wi = 0; wi < wlList.length; wi++) {
    var wk = wlList[wi], nr = has(repBy[wk]) ? repBy[wk] : 0, nd = desBy[wk], wns = wk.split('/')[0];
    if (nr < 1) down.push(wk); else if (has(nd) && nr < nd) short.push(wk);
    repNs[wns] = (repNs[wns] || 0) + nr;
  }
  /* Bursa exports sign_total for every profile from startup, so a ready pod without it reports no agent telemetry */
  for (var nk in repNs) if (repNs[nk] > 0 && !(telBy[nk] >= repNs[nk])) dark.push(nk);
  if (!has(rep)) kpi('rep'); else {
    var rs = down.length ? 'bad' : (short.length ? 'warn' : 'ok');
    kpi('rep', n0(rep) + (has(des) ? '/' + n0(des) : ''), '', rs, rs === 'ok' ? 'every replica can sign' : (rs === 'bad' ? 'producers cannot sign' : 'reduced redundancy'));
    if (down.length) issue('bad', '<b>no agent replica is ready</b>' + (multi ? ' in ' + esc(names(down)) : '') + ', so the producers that depend on it cannot sign');
    if (short.length) issue('warn', multi ? 'agent replicas are short in <b>' + esc(names(short)) + '</b>' : 'only <b>' + n0(rep) + ' of ' + n0(des) + '</b> agent replicas are ready');
  }
  var tel = sum('TEL'), telAll = has(tel) && tel > 0 && !dark.length;
  var sok = one('SOK'), ser = one('SER'), nOk = has(sok) ? Math.round(sok) : undefined, nEr = has(ser) ? Math.round(ser) : 0;
  kpi('sgn', has(nOk) ? String(nOk) : undefined, 'ok', nEr ? 'bad' : 'ok', !has(nOk) ? 'no agent telemetry' : (nEr ? nEr + ' failed' : (nOk ? 'none failed' : 'no sign in this range')));
  if (nEr) issue('bad', plural(nEr, 'sign', 'signs') + ' <b>failed</b> inside the agent');
  var slow = maxRow(rows('AS')), gwBy = byLabel('GW', 'profile'), gw = slow ? gwBy[slow.l.profile] : undefined;
  kpi('ags', slow ? n0(slow.v * 1000) : undefined, 'ms', slow ? low(slow.v, 0.25, 0.4) : 'na', slow ? (slow.l.profile || '') + ' · mean' : 'no sign in this range');
  var share = slow && has(gw) && slow.v > 0 ? Math.min(100, Math.round(gw / slow.v * 100)) : undefined;
  kpi('gw', has(gw) ? n0(gw * 1000) : undefined, 'ms', has(gw) ? low(gw, 0.1, 0.4) : 'na', has(share) ? (share >= 99 ? 'nearly all' : share + '%') + ' of the sign mean' : 'no write in this range');
  if (slow && slow.v >= 0.25) issue(low(slow.v, 0.25, 0.4), 'a sign for <b>' + esc(slow.l.profile) + '</b> takes ' + ms(slow.v) + ' inside the agent' + (has(share) ? '; the mean slot-guard write is ' + (share >= 99 ? 'nearly all' : share + '%') + ' of that' : ''));
  if (has(gw) && gw >= 0.1) issue(low(gw, 0.1, 0.4), 'a slot-guard write for <b>' + esc(slow.l.profile) + '</b> takes ' + ms(gw) + ' on average');
  var eq = one('EQ'), rb = one('RB'), se = one('SE');
  var nEq = has(eq) ? Math.round(eq) : 0, nRb = has(rb) ? Math.round(rb) : 0, nSe = has(se) ? Math.round(se) : 0, blocked = nEq + nRb + nSe;
  kpi('grd', has(eq) || has(rb) || has(se) ? String(blocked) : undefined, '', nEq || nSe ? 'bad' : (nRb ? 'warn' : 'ok'), blocked ? nEq + ' equivocation · ' + nRb + ' rollback · ' + nSe + ' store' : 'no refusal, no store error');
  if (nEq) issue('bad', 'the slot guard refused <b>' + plural(nEq, 'double sign', 'double signs') + '</b> (two producers active on one pool)');
  if (nSe) issue('bad', plural(nSe, 'slot-guard store call', 'slot-guard store calls') + ' failed (check the slot-guard store)');
  if (nRb) issue('warn', 'the slot guard refused ' + plural(nRb, 'rollback sign', 'rollback signs'));
  var exh = rows('EXH').map(function (r) { return r.l.profile });
  if (exh.length) issue('bad', 'the KES key for <b>' + esc(names(exh)) + '</b> is exhausted and can no longer sign');
  var fresh = rows('FR').map(function (r) { return r.l.profile });
  if (fresh.length) issue('warn', 'the slot guard for <b>' + esc(names(fresh)) + '</b> started with no record of earlier signs');
  var kes = minRow(rows('KES'));
  kpi('kes', kes ? n0(kes.v) : undefined, 'periods', kes ? high(kes.v, 9, 4) : 'na', kes ? (kes.l.profile || '') + ' · ' + n0(kes.v * 1.5) + ' days' : '');
  if (kes && kes.v < 9) issue(high(kes.v, 9, 4), 'the key for <b>' + esc(kes.l.profile) + '</b> has ' + plural(Math.round(kes.v), 'KES period', 'KES periods') + ' left');
  var mem = one('MEM'); if (has(mem) && mem >= 0.8) issue(low(mem, 0.8, 0.95), 'a replica uses <b>' + n0(mem * 100) + '%</b> of its memory limit');
  var rst = one('RST'); if (has(rst) && Math.round(rst) > 0) issue('warn', 'the agent restarted ' + plural(Math.round(rst), 'time', 'times') + ' in 24 h');
  if (!issues.length && !has(rep) && !has(sok) && !kes) { verdict('No KES agent metrics in this time range.', 'na') }
  else if (!issues.length && !telAll) {
    verdict((has(tel) && tel > 0 ? (multi ? 'Not every ready replica in ' + esc(names(dark)) + ' reports agent metrics' : 'Only ' + n0(tel) + (has(rep) ? ' of ' + n0(rep) : '') + ' ready replicas report agent metrics') : 'No agent metrics came back' + (has(rep) ? ' for the ' + plural(Math.round(rep), 'ready replica', 'ready replicas') : '')) + ', so signing and the slot guard cannot be judged.', 'na');
  }
  else if (!issues.length) {
    verdict((has(rep) ? (rep === 2 ? 'Both replicas are ready' : plural(Math.round(rep), 'replica is', 'replicas are') + ' ready') : 'The agent is answering') +
      (nOk ? '; ' + plural(nOk, 'sign', 'signs') + ', none failed or refused' : '; no sign was requested in this range') +
      (slow ? '; a sign takes ' + ms(slow.v) + ' inside the agent' + (has(share) ? '; the mean slot-guard write is ' + (share >= 99 ? 'nearly all' : share + '%') + ' of that' : '') : '') + '.', 'ok');
  } else {
    issues.sort(function (x, y) { return RANK[y.st] - RANK[x.st] });
    var txt = issues.slice(0, 3).map(function (x) { return x.text }).join('; ');
    if (issues.length > 3) txt += '; and ' + (issues.length - 3) + ' more';
    if (txt.charAt(0) !== '<') txt = txt.charAt(0).toUpperCase() + txt.slice(1);
    verdict(txt + '.' + (has(rep) && rep >= 1 ? ' ' + n0(rep) + (has(des) ? ' of ' + n0(des) : '') + ' replicas ready' + (has(nOk) ? ', ' + plural(nOk, 'sign', 'signs') + ' served.' : '.') : ''), sev);
  }

  } catch (e) {
    var v = document.getElementById(ROOT_ID + '-verdict');
    if (v) v.textContent = 'Header script error: ' + (e && e.message ? e.message : e);
  }
})();
